52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
63	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        if (owner.getEmail() != null) {
114	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
115	            if (!EMAIL_PATTERN.matcher(email).matches()) {
116	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
117	            }
118	            owner.setEmail(email);
119	        }
120	        String telephone = normalizeTelephone(owner.getTelephone());
121	        if (telephone == null) {
122	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	        }
124	        owner.setTelephone(telephone);
125	        if (owner.getRegistrationDate() == null) {
126	            owner.setRegistrationDate(LocalDate.now());
127	        }
128	        if (isTelephoneInUse(telephone)) {
129	            return new ResponseEntity<>(HttpStatus.CONFLICT);
130	        }
131	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && isHouseholdInUse(owner)) {
132	            return new ResponseEntity<>(HttpStatus.CONFLICT);
133	        }
134	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
135	        owner.setHouseholdId(householdId(owner));
136	        this.clinicService.saveOwner(owner);
137	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
138	        headers.setLocation(UriComponentsBuilder.newInstance()
139	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
140	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
